:root {
  color-scheme: light;
  --workspace-background: #f5f7fa;
  --workspace-surface: #fff;
  --workspace-text: #17212f;
  --workspace-muted: #4d5968;
  --workspace-border: #d9e1e9;
  --workspace-radius: 12px;
  --workspace-gutter: clamp(16px, 4vw, 40px);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif;
  line-height: 1.5;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--workspace-background);
  color: var(--workspace-text);
}

.workspace {
  max-width: 1100px;
  margin-inline: auto;
  padding: var(--workspace-gutter);
}

.workspace__header {
  padding-block: 12px 24px;
}

.workspace__header h1 {
  margin: 0;
  font-size: clamp(24px, 4vw, 34px);
  line-height: 1.25;
}

.workspace__empty {
  display: grid;
  min-height: 180px;
  place-items: center;
  padding: var(--workspace-gutter);
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
  color: var(--workspace-muted);
}

.workspace__empty p {
  margin: 0;
}
